function person({coat=M.cloth,hat=false,weapon=true,scale=1}={}){const root=group();root.scale.setScalar(scale);const rig={root,parts:[]};const torso=box(root,.56,.76,.35,coat,0,1.15,0);rig.torso=torso;box(root,.62,.18,.4,M.dark,0,1.48,0);ball(root,.24,M.skin,0,1.8,0,.9,1.05,.84);const hatMesh=hat?new THREE.Mesh(new THREE.ConeGeometry(.42,.17,8),M.dark):null;if(hatMesh){hatMesh.position.set(0,2.04,0);root.add(hatMesh);rig.parts.push(hatMesh)}box(root,.46,.24,.34,M.dark,0,.7,0);rig.legs=[];for(const x of [-.16,.16])rig.legs.push(box(root,.19,.57,.22,coat,x,.32,0));rig.arm=group(root,-.34,1.42,0);box(rig.arm,.18,.48,.19,coat,0,-.17,0);ball(rig.arm,.12,M.skin,0,-.42,0);rig.sword=group(rig.arm,0,-.47,.05);box(rig.sword,.045,.36,.055,M.wood,0,-.12,0);box(rig.sword,.35,.045,.07,M.gold,0,-.32,0);const blade=box(rig.sword,.075,weapon?1.05:.65,.035,M.blade,0,-.82,0);blade.rotation.z=-.035;rig.weapon=weapon;rig.walk=0;return rig}
const player=person({coat:M.cloth,hat:true});player.root.position.set(-2,0,6);player.root.rotation.y=Math.PI;
function makeNPC(name,x,z,coat,kind){const rig=person({coat,hat:kind==='ferryman',weapon:false,scale:kind==='elder'?.92:1});rig.root.position.set(x,0,z);rig.root.rotation.y=Math.PI;const badge=ball(rig.root,.09,M.gold,0,2.18,0);badge.material=badge.material.clone();badge.material.emissive=new THREE.Color(0x55401b);const item={kind,name,rig,position:new THREE.Vector3(x,0,z),interact:true};entities.push(item);return item}
const entities=[];const ferryman=makeNPC('Toma, the Ferryman',-2,4.2,M.red,'ferryman');const herbalist=makeNPC('Mina, the Herbalist',24,-14,M.leaf2,'healer');const woodcarver=makeNPC('Ren, the Bellmaker',19,-20,M.gold,'elder');
function makeEnemy(name,x,z,boss=false){const rig=person({coat:boss?M.red:M.dark,hat:true,weapon:true,scale:boss?1.2:1});rig.root.position.set(x,0,z);rig.root.rotation.y=Math.PI;const hp=boss?180:60,item={kind:'enemy',name,rig,position:new THREE.Vector3(x,0,z),hp,maxHp:hp,boss,alive:true,home:new THREE.Vector3(x,0,z),state:'idle',timer:rand()*1.5,attackHit:false,flash:0};entities.push(item);return item}
