const shards=[makeShard('Bell shard · salt',27,-13),makeShard('Bell shard · root',-25,10),makeShard('Bell shard · ember',1,-37)];
const shrineNodes=[{name:'West shrine',position:new THREE.Vector3(-27,0,8)},{name:'Bell shrine',position:new THREE.Vector3(0,0,-39)}];for(const s of shrineNodes)entities.push({kind:'shrine',name:s.name,position:s.position,interact:true});
// Simple island-wide journal progression.
let state='intro',time=0,last=0,hp=100,tonics=3,attackCd=0,dodge=0,invuln=0,attackAnim=0,questStage=0,toastTimer=0,dialogueDone=null,dialogueLines=[],dialogueIndex=0,worldClock=0;
const keys={};
function say(text,duration=2){$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=duration}
function journal(){const count=shards.filter(s=>s.collected).length;let text='Speak with Toma at the old bridge.';if(questStage===1)text=`Find the three bell shards · ${count}/3 recovered.`;if(questStage===2)text='Climb to the northern shrine. Defeat the Bell Warden.';if(questStage===3)text='Return to Toma at the old bridge.';if(questStage===4)text='The bell is whole. Wander freely, if you wish.';$('#questText').textContent=text;$('#hpnum').textContent=Math.ceil(hp);$('#hpbar').style.width=hp+'%';$('#healnum').textContent=tonics;$('#spiritbar').style.width=(100-Math.max(0,attackCd)*100)+'%'}
function openDialogue(speaker,title,text,onClose){$('#speaker').textContent=speaker;$('#dialogTitle').textContent=title;$('#dialogText').textContent=text;$('#dialogue').classList.remove('hidden');state='dialog';dialogueDone=onClose||null;}
$('#dialogNext').onclick=()=>{if(dialogueDone){const cb=dialogueDone;dialogueDone=null;$('#dialogue').classList.add('hidden');state='play';cb()}else{$('#dialogue').classList.add('hidden');state='play'}};
function speak(entity){if(entity.kind==='ferryman'){if(questStage===0){openDialogue('TOMA · THE FERRYMAN','A coast without a bell','The valley has lost its warning. Three notes were scattered: one beneath the salt roof, one in the deep roots, and one at the old altar. Bring them home.');questStage=1;journal()}else if(questStage===1&&shards.every(s=>s.collected)){openDialogue('TOMA · THE FERRYMAN','The mountain has one more answer','Good. The Warden guards the bell at the northern shrine. Take the road through the gate. When the steel falls quiet, come find me.');questStage=2;journal()}else if(questStage===3){questStage=4;journal();openDialogue('TOMA · THE FERRYMAN','Listen','There. A small sound, but it reached the whole coast. You gave this place another morning. Thank you, wanderer.',()=>{$('#resultTitle').textContent='THE BELL RETURNS';$('#resultEyebrow').textContent='A NEW DAWN OVER SALTMERE';$('#resultText').textContent='The main story is complete. The open wilds remain yours to explore.';$('#result').classList.remove('hidden');state='play'})}else openDialogue('TOMA · THE FERRYMAN','The old bridge','The road is patient. Follow the little bells. They know the way.')}
else if(entity.kind==='healer'){tonics=Math.min(5,tonics+2);hp=Math.min(100,hp+25);journal();openDialogue('MINA · HERBALIST','A little warmth','Take these. The forest has been cruel enough already. I left another tonic near the lantern road.');}
else if(entity.kind==='elder')openDialogue('REN · BELLMAKER','The shape of a note','The shards hum when you face the old altar. One is near the salt huts. One lies where the roots knot. Keep your blade low unless the ronin finds you first.');
else if(entity.kind==='shrine'){tonics=Math.min(5,tonics+1);hp=Math.min(100,hp+35);journal();say('SHRINE RESTORED · +1 TONIC',2);}
else if(entity.kind==='shard'){if(!entity.collected){entity.collected=true;entity.rig.root.visible=false;const n=shards.filter(s=>s.collected).length;say(`BELL SHARD RECOVERED · ${n}/3`,2.5);journal();if(n===3)say('ALL THREE NOTES FOUND · RETURN TO TOMA',3)} }
else if(entity.kind==='enemy'&&entity.alive){if(entity.boss)say('THE WARDEN BLOCKS THE SHRINE',1.8);else say(`${entity.name} · DRAW YOUR BLADE`,1.5)} }
function interact(){if(state!=='play')return;const near=nearestEntity(3.2);if(!near){say('ONLY WIND AND FOOTSTEPS',1);return}if(near.kind==='enemy'&&near.alive){say('THEY HAVE ALREADY SEEN YOU',1);return}speak(near)}
function nearestEntity(max=3){let best=null,dBest=max;for(const e of entities){if(e.kind==='enemy'&&!e.alive)continue;if(e.kind==='shard'&&e.collected)continue;const d=Math.hypot(player.root.position.x-e.position.x,player.root.position.z-e.position.z);if(d<dBest){best=e;dBest=d}}return best}
function attack(){if(state!=='play'||attackCd>0)return;attackCd=.48;attackAnim=.36;player.rig?.();const target=enemies.filter(e=>e.alive).sort((a,b)=>a.position.distanceTo(player.root.position)-b.position.distanceTo(player.root.position))[0];if(!target)return;const d=target.position.distanceTo(player.root.position);if(d>2.65)return;const toward=Math.atan2(target.position.x-player.root.position.x,target.position.z-player.root.position.z),diff=Math.atan2(Math.sin(toward-player.root.rotation.y),Math.cos(toward-player.root.rotation.y));if(Math.abs(diff)>.95)return;target.hp-=target.boss?21:34;target.flash=.18;target.rig.torso.material=target.rig.torso.material.clone();target.rig.torso.material.emissive=new THREE.Color(0x8c3324);say(target.hp<=0?'A CLEAN CUT':'STEEL MEETS STEEL',.75);if(target.hp<=0){target.alive=false;target.rig.root.visible=false;target.interact=false;say(target.boss?'THE WARDEN IS SILENT':'RONIN DEFEATED',2);if(target.boss){questStage=3;journal();say('THE WARDEN FALLS · RETURN TO TOMA',3)}}}
function dodgeAction(){if(state!=='play'||dodge>0)return;dodge=.5;invuln=.48;let mx=(keys.KeyD||keys.ArrowRight||keys.Dirright?1:0)-(keys.KeyA||keys.ArrowLeft||keys.Dirleft?1:0),mz=(keys.KeyS||keys.ArrowDown||keys.Dirdown?1:0)-(keys.KeyW||keys.ArrowUp||keys.Dirup?1:0);if(!mx&&!mz){mx=Math.sin(player.root.rotation.y);mz=Math.cos(player.root.rotation.y)}const l=Math.hypot(mx,mz)||1;player.root.position.x+=mx/l*3.1;player.root.position.z+=mz/l*3.1}
function heal(){if(state!=='play'||tonics<=0||hp>=100)return;tonics--;hp=Math.min(100,hp+38);say('TONIC · +38 VITALITY',1.5);journal()}

